{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-n4wZWQ/src/address.js","content":"/**
 * Cell address parsing, canonicalization, and column arithmetic.
 *
 * Addresses are one or two letters naming a column (A..Z, AA..ZZ) followed
 * by one to three digits naming a row of at least 1. Columns use the same
 * bijective base-26 numbering spreadsheets use (A=1, Z=26, AA=27, ZZ=702).
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Converts an upper-cased column letters string to its 1-based index. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Converts a 1-based column index back to upper-case letters. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parses a candidate address word (case-insensitive). Returns
 * { valid: false } when the shape or row is outside the addressable range,
 * or { valid: true, col, row, text } with the canonical upper-case text.
 */
export function addressInfo(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return { valid: false }
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const col = colToNum(letters)
  return { valid: true, col, row, text: letters + String(row) }
}

/** Sort comparator: ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const ia = addressInfo(a)
  const ib = addressInfo(b)
  if (ia.col !== ib.col) return ia.col - ib.col
  return ia.row - ib.row
}

/**
 * Expands a range between two address words to the list of addresses it
 * covers, in ascending column then ascending row order, regardless of which
 * corner each endpoint names. Returns { ok: false } when either endpoint is
 * outside the addressable range.
 */
export function expandRange(fromWord, toWord) {
  const a = addressInfo(fromWord)
  const b = addressInfo(toWord)
  if (!a.valid || !b.valid) return { ok: false }
  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const addresses = []
  for (let c = minCol; c <= maxCol; c++) {
    const letters = numToCol(c)
    for (let r = minRow; r <= maxRow; r++) addresses.push(letters + String(r))
  }
  return { ok: true, addresses }
}
"}

