{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-n4wZWQ/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const NUMBER_RE = /^[0-9]+(\.[0-9]+)?/
const WORD_RE = /^[A-Za-z]+[0-9]*/

/** Thrown when a formula body contains a character outside the grammar. */
export class LexError extends Error {}

/**
 * Tokenizes a formula body. Throws LexError on any character the grammar
 * does not define.
 */
export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const c = body[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      const m = NUMBER_RE.exec(body.slice(i))
      tokens.push({ type: 'NUMBER', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = WORD_RE.exec(body.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    if (c === '<') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '<=' })
        i += 2
      } else if (body[i + 1] === '>') {
        tokens.push({ type: 'OP', value: '<>' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '>' })
        i++
      }
      continue
    }
    if (c === '=' || c === '+' || c === '-' || c === '*' || c === '/' || c === '^') {
      tokens.push({ type: 'OP', value: c })
      i++
      continue
    }
    throw new LexError(`unexpected character ${c}`)
  }
  return tokens
}
"}

