 * The four value kinds a cell can hold: number, text, boolean, and error.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function num(v) {
  return { kind: 'num', v }
}

export function text(v) {
  return { kind: 'text', v }
}

export function bool(v) {
  return { kind: 'bool', v }
}

export function err(token) {
  return { kind: 'err', v: token }
}

export function isErr(v) {
  return v.kind === 'err'
}

/**
 * Reads a value as a number for arithmetic. Returns { ok: true, n } or
 * { ok: false, err: <error value> }.
 */
export function toNumber(v) {
  if (v.kind === 'err') return { ok: false, err: v }
  if (v.kind === 'num') return { ok: true, n: v.v }
  if (v.kind === 'bool') return { ok: true, n: v.v ? 1 : 0 }
  return { ok: false, err: err('#VALUE!') }
}

/** Wraps a computed number, turning non-finite results into #DIV/0!. */
export function finiteOrDivZero(n) {
  if (!isFinite(n)) return err('#DIV/0!')
  return num(n)
}

const KIND_RANK = { num: 0, text: 1, bool: 2 }

/** Compares two non-error values per the cross-kind ordering rules. */
export function compareValues(a, b) {
  const ra = KIND_RANK[a.kind]
  const rb = KIND_RANK[b.kind]
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.kind === 'bool') {
    const an = a.v ? 1 : 0
    const bn = b.v ? 1 : 0
    return an - bn
  }
