export function evalCell(addr, ctx) {
  if (ctx.cache.has(addr)) return ctx.cache.get(addr)
  if (ctx.visiting.has(addr)) return err('#CYCLE!')
  const cell = ctx.cells.get(addr)
  if (!cell) {
    const v = num(0)
    ctx.cache.set(addr, v)
    return v
  }
  ctx.visiting.add(addr)
  let result
  try {
    result = evalContent(cell.content, ctx)
  } finally {
    ctx.visiting.delete(addr)
  }
  ctx.cache.set(addr, result)
  return result
}

