  const info = addressInfo(node.name)
  if (!info.valid) return err('#REF!')
  return evalCell(info.text, ctx)
}

/**
 * Expands a range AST node to its covered addresses, or a #REF! error when
 * an endpoint is outside the addressable range.
 */
function expandRangeNode(node) {
  const r = expandRange(node.from, node.to)
  if (!r.ok) return { ok: false, error: err('#REF!') }
  return { ok: true, addresses: r.addresses }
}

