  if (argNode.type === 'range') {
    const exp = expandRangeNode(argNode)
    if (!exp.ok) return exp.error
    const vals = exp.addresses.map((a) => evalCell(a, ctx))
    for (const v of vals) if (isErr(v)) return v
    if (vals.length === 1) return vals[0]
    return err('#ERR!')
  }
  return evalExpr(argNode, ctx)
