/** Rounds to ten significant digits, the way toPrecision + reparse does. */
function roundToTenSignificantDigits(n) {
  if (n === 0 || !isFinite(n)) return n
  return parseFloat(n.toPrecision(10))
}

export function formatValue(value) {
  switch (value.kind) {
    case 'num':
      return String(roundToTenSignificantDigits(value.v))
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'err':
      return value.v
    default:
      throw new Error(`unknown value kind ${value.kind}`)
  }
}
"}

