/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { createContext, evalCell } from './evaluator.js'
import { formatValue } from './format.js'
import { collectDeps } from './deps.js'
import { compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')
  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`line ${e.line}: ${e.message}`)
    throw e
  }

  const addresses = [...cells.keys()].sort(compareAddresses)
  const lines = []

  if (mode === 'values') {
    const ctx = createContext(cells)
    for (const addr of addresses) {
      const value = evalCell(addr, ctx)
      lines.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addresses) {
      const deps = [...collectDeps(cells.get(addr).content)].sort(compareAddresses)
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.map((l) => l + '\n').join(''))
  process.exit(0)
}

main()
"}

